{"path": "stage1.py", "content": """"Stage 1: parse the orders CSV into a list of dicts."""

import csv


def parse_orders(path):
    """Read ``path`` (header ``id,qty,price``) and return row dicts.

    Each row is ``{"id": int, "qty": int, "price": int}`` in file order.
    """
    rows = []
    with open(path, newline="", encoding="utf-8") as fh:
        reader = csv.DictReader(fh)
        for raw in reader:
            rows.append(
                {
                    "id": int(raw["id"]),
                    "qty": int(raw["qty"]),
                    "price": int(raw["price"]),
                }
            )
    return rows
"}

{"path": "stage2.py", "content": """"Stage 2: drop rows that carry no order quantity."""


def filter_orders(rows):
    """Return the rows with ``qty > 0``, preserving the original order."""
    return [row for row in rows if row["qty"] > 0]
"}

{"path": "stage3.py", "content": """"Stage 3: aggregate quantity per price."""


def total_by_price(rows):
    """Return ``{price: total qty}``, summing qty for equal prices."""
    totals = {}
    for row in rows:
        totals[row["price"]] = totals.get(row["price"], 0) + row["qty"]
    return totals
"}

{"path": "stage4.py", "content": """"Stage 4: render the aggregated totals as a report string."""


def report(totals):
    """Return ``"<price>:<qty>"`` lines sorted by ascending price."""
    return "".join(f"{price}:{totals[price]}\n" for price in sorted(totals))
"}
